import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    private static volatile boolean running = true;
    private static volatile int unsafeCounter = 0;
    private static final AtomicInteger safeCounter = new AtomicInteger();
    private static volatile Singleton singleton;

    public static void main(String[] args) throws Exception {
        demonstrateStopFlag();
        demonstrateNonAtomicIncrement();
        demonstrateDclPublication();
    }

    static void demonstrateStopFlag() throws InterruptedException {
        AtomicInteger loops = new AtomicInteger();
        Thread worker = new Thread(() -> {
            while (running) {
                loops.incrementAndGet();
            }
        }, "volatile-stop-worker");
        worker.start();
        Thread.sleep(30);
        running = false;
        worker.join(1000);
        System.out.println("stopFlag workerAlive=" + worker.isAlive()
                + ", loops=" + loops.get());
        assert !worker.isAlive();
    }

    static void demonstrateNonAtomicIncrement() throws Exception {
        unsafeCounter = 0;
        CyclicBarrier beforeRead = new CyclicBarrier(2);
        CyclicBarrier beforeWrite = new CyclicBarrier(2);
        Runnable lostUpdate = () -> {
            await(beforeRead);
            int snapshot = unsafeCounter;
            await(beforeWrite);
            unsafeCounter = snapshot + 1;
        };
        Thread t1 = new Thread(lostUpdate, "volatile-race-1");
        Thread t2 = new Thread(lostUpdate, "volatile-race-2");
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.println("unsafeCounter=" + unsafeCounter);
        assert unsafeCounter == 1;

        safeCounter.set(0);
        CountDownLatch done = new CountDownLatch(2);
        Runnable atomicUpdate = () -> {
            safeCounter.incrementAndGet();
            done.countDown();
        };
        new Thread(atomicUpdate, "atomic-1").start();
        new Thread(atomicUpdate, "atomic-2").start();
        done.await();
        System.out.println("safeCounter=" + safeCounter.get());
        assert safeCounter.get() == 2;
    }

    static void demonstrateDclPublication() throws InterruptedException {
        Set<Integer> identities = ConcurrentHashMap.newKeySet();
        CountDownLatch done = new CountDownLatch(8);
        for (int i = 0; i < 8; i++) {
            new Thread(() -> {
                Singleton value = getSingleton();
                identities.add(System.identityHashCode(value));
                assert value.answer == 42;
                done.countDown();
            }, "dcl-reader-" + i).start();
        }
        done.await();
        System.out.println("singletonInstances=" + identities.size());
        assert identities.size() == 1;
    }

    static Singleton getSingleton() {
        Singleton local = singleton;
        if (local == null) {
            synchronized (Main.class) {
                local = singleton;
                if (local == null) {
                    local = new Singleton(42);
                    singleton = local;
                }
            }
        }
        return local;
    }

    static void await(CyclicBarrier barrier) {
        try {
            barrier.await();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static final class Singleton {
        final int answer;

        Singleton(int answer) {
            this.answer = answer;
        }
    }
}
